import { z } from "zod";

export const BookingSchema = z.object({
  fullName: z.string().trim().min(3, "Name must be at least 3 characters").max(80),
  email: z.string().trim().email("Please provide a valid email address"),
  phone: z.string().trim().regex(/^\+?[1-9]\d{7,14}$/, "Invalid international phone number"),
  visaType: z.enum(["tourist_30", "tourist_60", "transit"]),
  passengersCount: z.coerce.number().int().min(1).max(10),
  travelDate: z.string().refine((date) => !isNaN(Date.parse(date)), {
    message: "Valid travel date required",
  }),
});

export type BookingInput = z.infer<typeof BookingSchema>;

"use server";

import { BookingSchema } from "@/lib/validations/booking";

export type ActionState = {
  success: boolean;
  message: string;
  errors?: Record<string, string[]>;
};

export async function submitBookingAction(
  prevState: ActionState,
  formData: FormData
): Promise<ActionState> {
  const rawData = Object.fromEntries(formData.entries());
  const validationResult = BookingSchema.safeParse(rawData);

  if (!validationResult.success) {
    return {
      success: false,
      message: "Validation failed. Please verify your entries.",
      errors: validationResult.error.flatten().fieldErrors,
    };
  }

  const cleanData = validationResult.data;

  try {
    // cleanData is fully typed as BookingInput
    // Proceed to database write or payment gateway call
    return {
      success: true,
      message: `Booking received for ${cleanData.fullName}. Processing request.`,
    };
  } catch (error) {
    return {
      success: false,
      message: "Database operation failed. Please try again later.",
    };
  }
}

"use client";

import { useActionState } from "react";
import { submitBookingAction, type ActionState } from "@/app/actions/booking";

const initialState: ActionState = {
  success: false,
  message: "",
};

export function BookingForm() {
  const [state, formAction, isPending] = useActionState(submitBookingAction, initialState);

  return (
    <form action={formAction} className="space-y-4 max-w-md mx-auto">
      <div>
        <label htmlFor="fullName" className="block text-sm font-medium">Full Name</label>
        <input id="fullName" name="fullName" required className="border rounded p-2 w-full" />
        {state.errors?.fullName && (
          <p className="text-red-500 text-xs mt-1">{state.errors.fullName[0]}</p>
        )}
      </div>

      <div>
        <label htmlFor="email" className="block text-sm font-medium">Email</label>
        <input id="email" name="email" type="email" required className="border rounded p-2 w-full" />
        {state.errors?.email && (
          <p className="text-red-500 text-xs mt-1">{state.errors.email[0]}</p>
        )}
      </div>

      <button
        type="submit"
        disabled={isPending}
        className="bg-blue-600 text-white py-2 px-4 rounded disabled:opacity-50"
      >
        {isPending ? "Submitting..." : "Book Application"}
      </button>

      {state.message && (
        <p className={`text-sm ${state.success ? "text-green-600" : "text-red-600"}`}>
          {state.message}
        </p>
      )}
    </form>
  );
}
